export const getStartReviewUrl = (id: string) => {
  return `/api/v1/approval-cases/${id}/start-review`
}

/**
 * @summary Start the review (SUBMITTED → IN_REVIEW) after verifying hash and signature
 */
export const startReview = async (
  id: string,
  headers?: StartReviewHeaders,
  options?: Parameters<typeof apiFetch>[1],
): Promise<ApprovalCaseDetailDto> => {
  return apiFetch<ApprovalCaseDetailDto>(getStartReviewUrl(id), {
    ...options,
    method: 'POST',
    headers: getHeaders(headers, options?.headers),
  })
}

export const getStartReviewMutationKey = () => ['startReview'] as const

export const getStartReviewMutationOptions = <TError = ErrorType<ProblemDetail>, TContext = unknown>(options?: {
  mutation?: UseMutationOptions<Awaited<ReturnType<typeof startReview>>, TError, StartReviewMutationVariables, TContext>
  request?: SecondParameter<typeof apiFetch>
}): UseMutationOptions<Awaited<ReturnType<typeof startReview>>, TError, StartReviewMutationVariables, TContext> => {
  const mutationKey = getStartReviewMutationKey()
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined }

  const mutationFn: MutationFunction<Awaited<ReturnType<typeof startReview>>, StartReviewMutationVariables> = (
    props,
  ) => {
    const { id, headers } = props ?? {}

    return startReview(id, headers, requestOptions)
  }

  return { mutationFn, ...mutationOptions }
}

export type StartReviewMutationResult = NonNullable<Awaited<ReturnType<typeof startReview>>>

export type StartReviewMutationError = ErrorType<ProblemDetail>
export type StartReviewMutationVariables = { id: string; headers?: StartReviewHeaders }

/** @summary Start the review (SUBMITTED → IN_REVIEW) after verifying hash and signature */
export const useStartReview = <TError = ErrorType<ProblemDetail>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof startReview>>,
      TError,
      StartReviewMutationVariables,
      TContext
    >
    request?: SecondParameter<typeof apiFetch>
  },
  queryClient?: QueryClient,
): UseMutationResult<Awaited<ReturnType<typeof startReview>>, TError, StartReviewMutationVariables, TContext> => {
  return useMutation(getStartReviewMutationOptions(options), queryClient)
}
